module longest_repeated_substring(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] char0, char1, char2, char3, char4, char5, char6, char7,\n    input [7:0] char8, char9, char10, char11, char12, char13, char14, char15,\n    input [3:0] length_in,\n    output reg [4:0] result,\n    output reg done\n);\n\n    // State definitions with explicit widths\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] INIT = 3'd1;\n    localparam [2:0] CHECK = 3'd2;\n    localparam [2:0] NEXT_LEN = 3'd3;\n    localparam [2:0] FINISHED = 3'd4;\n\n    reg [2:0] state, next_state;\n    reg [4:0] current_len, next_current_len;\n    reg [3:0] start_i, next_start_i;\n    reg [3:0] start_j, next_start_j;\n    reg [4:0] best_result, next_best_result;\n    reg [7:0] chars [0:15];\n\n    // Char array assignments\n    always @(*) begin\n        chars[0] = char0;  chars[1] = char1;\n        chars[2] = char2;  chars[3] = char3;\n        chars[4] = char4;  chars[5] = char5;\n        chars[6] = char6;  chars[7] = char7;\n        chars[8] = char8;  chars[9] = char9;\n        chars[10] = char10; chars[11] = char11;\n        chars[12] = char12; chars[13] = char13;\n        chars[14] = char14; chars[15] = char15;\n    end\n\n    // Combinational substring comparison\n    reg substr_match;\n    integer k;\n    always @(*) begin\n        substr_match = 1'b1;\n        if (current_len == 5'd0 || start_i + current_len > length_in || start_j + current_len > length_in) begin\n            substr_match = 1'b0;\n        end else begin\n            for (k = 0; k < 15; k = k + 1) begin\n                if (k < current_len) begin\n                    if (chars[start_i + k] != chars[start_j + k]) begin\n                        substr_match = 1'b0;\n                    end\n                end\n            end\n        end\n    end\n\n    // State register\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            current_len <= 5'd0;\n            start_i <= 4'd0;\n            start_j <= 4'd0;\n            best_result <= 5'd0;\n            done <= 1'b0;\n            result <= 5'd0;\n        end else begin\n            state <= next_state;\n            current_len <= next_current_len;\n            start_i <= next_start_i;\n            start_j <= next_start_j;\n            best_result <= next_best_result;\n            done <= (next_state == FINISHED);\n            result <= next_best_result;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        next_current_len = current_len;\n        next_start_i = start_i;\n        next_start_j = start_j;\n        next_best_result = best_result;\n\n        case (state)\n            IDLE: begin\n                if (start) begin\n                    next_state = INIT;\n                end\n            end\n            \n            INIT: begin\n                next_current_len = (length_in > 4'd1) ? (length_in - 4'd1) : 5'd0;\n                next_start_i = 4'd0;\n                next_start_j = 4'd1;\n                next_best_result = 5'd0;\n                next_state = CHECK;\n            end\n            \n            CHECK: begin\n                if (substr_match) begin\n                    next_best_result = current_len;\n                    next_state = NEXT_LEN;\n                end else begin\n                    if (start_j < (length_in - current_len)) begin\n                        next_start_j = start_j + 4'd1;\n                    end else begin\n                        next_start_j = start_i + 4'd2;\n                        next_start_i = start_i + 4'd1;\n                        if ((start_i + 4'd1) >= (length_in - current_len)) begin\n                            next_state = NEXT_LEN;\n                        end\n                    end\n                end\n            end\n            \n            NEXT_LEN: begin\n                if (current_len > 5'd1) begin\n                    next_current_len = current_len - 5'd1;\n                    next_start_i = 4'd0;\n                    next_start_j = 4'd1;\n                    next_state = CHECK;\n                end else begin\n                    next_state = FINISHED;\n                end\n            end\n            \n            FINISHED: begin\n                if (!start) begin\n                    next_state = IDLE;\n                end\n            end\n            \n            default: next_state = IDLE;\n        endcase\n    end\nendmodule